typedef struct {
    float ia, ib, ic;
    float theta_e;
    float id_ref, iq_ref;
} foc_state_t;

void foc_current_step(foc_state_t *s)
{
    float id = clarke_d(s->ia, s->ib, s->ic);
    float iq = clarke_q(s->ia, s->ib, s->ic);

    float id_err = s->id_ref - id;
    float iq_err = s->iq_ref - iq;

    float vd = pi_update(&pi_d, id_err);
    float vq = pi_update(&pi_q, iq_err);

    svpwm_apply(vd, vq, s->theta_e);
}
